document.addEventListener('click',event=>{if(!event.target.closest('[data-remediation-download]'))return;const csv='資產重要性,輕微,中度,重大,嚴重\n重大,43,4,0,0\n高,0,0,0,0\n中,0,0,0,0\n低,48,0,0,2';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='改善資料.csv';a.click();URL.revokeObjectURL(a.href)});
