document.addEventListener('click',event=>{const group=event.target.closest('[data-infra-filter-group]');if(group){const name=group.dataset.infraFilterGroup;vendorState.infraFilterOpen=vendorState.infraFilterOpen.includes(name)?vendorState.infraFilterOpen.filter(x=>x!==name):[...vendorState.infraFilterOpen,name];render();return}if(event.target.closest('[data-infra-clear]')){vendorState.infraFilters={};render()}});
document.addEventListener('change',event=>{if(!event.target.matches('[data-infra-filter-option]'))return;const name=event.target.dataset.infraFilterOption;const current=new Set(vendorState.infraFilters[name]||[]);event.target.checked?current.add(event.target.value):current.delete(event.target.value);vendorState.infraFilters[name]=[...current];render()});
document.addEventListener('change',event=>{if(event.target.matches('[data-asa-confirmed]')){vendorState.asaConfirmed=event.target.checked;render()}});
document.addEventListener('click',event=>{const more=event.target.closest('[data-asa-more]');if(more){const key=more.dataset.asaMore;vendorState.asaMore[key]=!vendorState.asaMore[key];render()}});
document.addEventListener('click',event=>{const group=event.target.closest('[data-threat-filter-group]');if(group){const name=group.dataset.threatFilterGroup;vendorState.threatFilterOpen=vendorState.threatFilterOpen.includes(name)?vendorState.threatFilterOpen.filter(x=>x!==name):[...vendorState.threatFilterOpen,name];render();return}if(event.target.closest('[data-threat-clear]')){vendorState.threatFilters={};render()}});
