document.addEventListener('click',event=>{const group=event.target.closest('[data-assessment-filter-group]');if(group){const y=window.scrollY;vendorState.assessmentFilterOpen=vendorState.assessmentFilterOpen===group.dataset.assessmentFilterGroup?'':group.dataset.assessmentFilterGroup;render();window.scrollTo(0,y);return}if(event.target.closest('[data-assessment-clear]')){vendorState.assessmentFilters={};render()}});
