function asaBars(items,max,stacked=false){return `<div class="asa-bars">${items.map(([name,a,b=0])=>`<button data-toast="已開啟 ${name} 的分析明細"><span>${name}</span><i><b style="width:${Math.max(4,a/max*100)}%">${a}</b>${stacked?`<em style="width:${Math.max(3,b/max*100)}%">${b}</em>`:''}</i></button>`).join('')}</div>`}
function asaAnalysisCard(title,subtitle,body,more,key){const open=vendorState.asaMore[key];return `<section class="asa-card"><header><h2>${title}</h2><span>ⓘ</span></header><p class="asa-subtitle">${subtitle}</p>${body}${more?`<button class="asa-more" data-asa-more="${key}">${open?'顯示較少':`＋${more} 個更多項目`}</button>`:''}${open?'<div class="asa-extra">更多分析項目已展開</div>':''}</section>`}
