 const impacted=[['176.221.32.169','PURE 2.0',45],['107.180.70.11','核心網路 ＋1',34],['176.221.32.31','PURE 2.0',33],['176.221.32.33','PURE 2.0 ＋1',33],['107.180.70.78','進階網路 ＋1',32],['107.180.70.73','進階網路 ＋1',32],['176.221.32.30','PURE 2.0',31],['176.221.32.39','PURE 2.0 ＋1',31],['185.99.234.50','核心網路 ＋5',29],['176.221.32.37','核心網路 ＋2',29]];
